<?php
session_start();
require_once __DIR__.'/config/db.php';
require_once __DIR__ . '/config/helpers.php';
if(!isset($_SESSION['user'])||!in_array($_SESSION['user']['role']??'', ['Principal','Admin'],true)){http_response_code(403);exit('Access denied.');}
$role=(string)$_SESSION['user']['role'];$eventID=(int)($_GET['eventID']??0);
if(empty($_SESSION['sems_csrf']))$_SESSION['sems_csrf']=bin2hex(random_bytes(32));$csrf=$_SESSION['sems_csrf'];
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['delete_feedback'])){if(!hash_equals($csrf,$_POST['csrf']??'')){http_response_code(400);exit('Refresh the page and try again.');}$feedbackID=(int)$_POST['delete_feedback'];$check=$pdo->prepare('SELECT photoPath,userID FROM feedback WHERE feedbackID=? AND eventID=?');$check->execute([$feedbackID,$eventID]);$feedbackRow=$check->fetch(PDO::FETCH_ASSOC);if(!$feedbackRow){http_response_code(404);exit('Feedback not found.');}$pdo->prepare('DELETE FROM feedback WHERE feedbackID=? AND eventID=?')->execute([$feedbackID,$eventID]);$notice=$pdo->prepare("INSERT INTO notifications(userID,title,message,link) VALUES(?,'Feedback removed by school administration','Your feedback for this event was removed by school administration. Contact the Principal if you think this was a mistake.',?)");$notice->execute([(int)$feedbackRow['userID'],'event_detail.php?eventID='.$eventID]);if(preg_match('#^uploads/feedback/[a-f0-9]{48}\.(jpg|png|webp)$#i',(string)$feedbackRow['photoPath']))@unlink(__DIR__.'/'.str_replace('/',DIRECTORY_SEPARATOR,$feedbackRow['photoPath']));header('Location: admin_event_detail.php?eventID='.$eventID.'#event-feedback');exit;}
$q=$pdo->prepare("SELECT e.*,u.userID AS organizerID,u.name AS organizer,u.email AS organizerEmail,(SELECT COUNT(*) FROM registrations r WHERE r.eventID=e.eventID) AS registrationTotal,(SELECT COUNT(*) FROM registrations r WHERE r.eventID=e.eventID AND r.status='Approved') AS approvedTotal,(SELECT COUNT(*) FROM registrations r WHERE r.eventID=e.eventID AND r.status='Pending Verification') AS pendingTotal,(SELECT COUNT(*) FROM registrations r WHERE r.eventID=e.eventID AND r.status='Rejected') AS rejectedTotal,(SELECT COUNT(*) FROM attendance a WHERE a.eventID=e.eventID AND a.status='Present') AS presentTotal,(SELECT COUNT(*) FROM attendance a WHERE a.eventID=e.eventID AND a.status='Absent') AS absentTotal,(SELECT COUNT(*) FROM payments p WHERE p.eventID=e.eventID) AS paymentTotal,(SELECT COALESCE(SUM(p.amount),0) FROM payments p WHERE p.eventID=e.eventID AND p.status='Verified') AS paymentVerified,(SELECT COUNT(*) FROM feedback f WHERE f.eventID=e.eventID) AS feedbackTotal FROM events e LEFT JOIN users u ON u.userID=e.createdBy WHERE e.eventID=?");$q->execute([$eventID]);$event=$q->fetch();
if(!$event){http_response_code(404);exit('Event not found.');}
$tasks=$pdo->prepare('SELECT t.taskTitle,t.taskDescription,t.taskStatus,u.userID,u.name,u.email FROM event_tasks t JOIN users u ON u.userID=t.assignedTo WHERE t.eventID=? ORDER BY u.name,t.taskTitle');$tasks->execute([$eventID]);$tasks=$tasks->fetchAll();
$rosterQ=$pdo->prepare("SELECT r.registrationID,r.registrationDate,r.status,s.studentID,s.class,s.formLevel,stu.userID AS studentUserID,stu.name AS studentName,stu.email AS studentEmail,a.status AS attendanceStatus,a.proofStatus,a.proofFile,(SELECT GROUP_CONCAT(CONCAT(fa.status,' · RM ',FORMAT(fa.amount,2),' — ',fa.reason) SEPARATOR ' | ') FROM financial_assistance fa WHERE fa.userID=stu.userID) AS assistanceDetails,(SELECT GROUP_CONCAT(CONCAT(p.status,' · RM ',FORMAT(p.amount,2),' · ',p.method,' · ',p.reference) SEPARATOR ' | ') FROM payments p WHERE p.eventID=r.eventID AND p.userID=stu.userID) AS paymentDetails FROM registrations r JOIN students s ON s.studentID=r.studentID JOIN users stu ON stu.userID=s.userID LEFT JOIN attendance a ON a.eventID=r.eventID AND a.studentID=r.studentID WHERE r.eventID=? ORDER BY FIELD(r.status,'Pending Verification','Approved','Rejected','Cancelled'),stu.name");$rosterQ->execute([$eventID]);$roster=$rosterQ->fetchAll();
$feedbackQ=$pdo->prepare('SELECT f.feedbackID,f.rating,f.comments,f.photoPath,f.submittedAt,u.name,u.userID FROM feedback f JOIN users u ON u.userID=f.userID WHERE f.eventID=? ORDER BY f.submittedAt DESC');$feedbackQ->execute([$eventID]);$feedback=$feedbackQ->fetchAll();
$current=$_SESSION['user'];$badge=strtoupper(substr((string)$current['name'],0,1));
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=school_h($event['eventName'])?> | SEMS</title><link rel="stylesheet" href="assets/style.css"><link rel="stylesheet" href="assets/portal.css?v=12"><link rel="stylesheet" href="assets/ui-polish.css?v=29"><script src="assets/proof-viewer.js?v=3" defer></script><script src="assets/confirm-actions.js?v=1" defer></script><link rel="stylesheet" href="assets/school-sphere.css?v=18"></head><body class="portal-body"><aside class="portal-sidebar"><a class="portal-brand" href="admin_dashboard.php">SEMS <small><?=school_h(strtoupper($role))?> PORTAL</small></a><nav><?php $detailNav=$role==='Principal'?['admin_dashboard.php'=>'Home','admin_events.php'=>'Event Management','admin_users.php'=>'Users','admin_reports.php'=>'Teacher Reports']:['admin_dashboard.php'=>'Home','admin_users.php'=>'Users','admin_events.php'=>'Event Management','admin_payments.php'=>'Payments','admin_attendance.php'=>'Attendance','admin_assistance.php'=>'Assistance','admin_reports.php'=>'Reports','calendar.php'=>'Calendar']; foreach($detailNav as $detailHref=>$detailLabel):?><a class="<?=$detailHref==='admin_events.php'?'active':''?>" href="<?=$detailHref?>"><?=school_h($detailLabel)?></a><?php endforeach;?></nav><a class="portal-logout" href="logout.php">Log Out</a></aside><main class="portal-main"><header class="portal-header"><div><small>EVENT MANAGEMENT</small><h1><?=school_h($event['eventName'])?></h1></div><div class="portal-account"><a class="portal-inbox" href="inbox.php">Inbox</a><a class="portal-profile-link" href="profile.php"><span class="portal-avatar portal-avatar-fallback"><?=school_h($badge)?></span><span class="portal-account-identity"><strong><?=school_h($current['name'])?></strong><small><?=school_h($role)?></small></span></a></div></header><div class="portal-content"><a class="portal-back-link" href="admin_events.php">← All events</a><section class="event-detail-hero"><div><?php if(!empty($event['eventPoster'])):?><img src="<?=school_h($event['eventPoster'])?>" alt="Event banner"><?php endif;?><div class="event-detail-title-row"><h2><?=school_h($event['eventName'])?></h2><span class="event-oversight-status"><?=school_h($event['status'])?></span></div><p><?=nl2br(school_h($event['description']?:'No student-facing description.'))?></p></div><aside><small>EVENT HANDLER</small><strong><?=school_h($event['organizer']??'Account unavailable')?></strong><span><?php if($publicId=school_public_person_id($pdo,(int)($event['organizerID']??0))):?><?=school_h($publicId)?> · <?php endif;?><?=school_h($event['organizerEmail']??'—')?></span><?php if(!empty($event['organizerEmail'])):?><a class="event-contact-organizer" href="mailto:<?=school_h($event['organizerEmail'])?>">Contact organizer</a><?php endif;?></aside></section>
<section class="portal-cards event-detail-metrics"><?php foreach([['Registrations',(int)$event['registrationTotal'],'Approved '.(int)$event['approvedTotal'].' · Pending '.(int)$event['pendingTotal'].' · Rejected '.(int)$event['rejectedTotal']],['Attendance',(int)$event['presentTotal'].' / '.(int)$event['approvedTotal'],'Present / approved · '.(int)$event['absentTotal'].' absent'],['Payments',(int)$event['paymentTotal'],'Verified total RM '.number_format((float)$event['paymentVerified'],2)],['Feedback',(int)$event['feedbackTotal'],'Student submissions']] as $metric):?><article><span><?=school_h($metric[0])?></span><strong><?=school_h($metric[1])?></strong><small><?=school_h($metric[2])?></small></article><?php endforeach;?></section>
<section class="portal-card"><h2>Event information</h2><div class="event-detail-facts"><p><small>Date and time</small><strong><?=school_h(date('d M Y',strtotime($event['eventDate'])).' · '.date('h:i A',strtotime($event['eventTime'])))?></strong></p><p><small>Location</small><strong><?=school_h($event['location'])?></strong></p><p><small>Registration closes</small><strong><?=school_h($event['registrationDeadline']?date('d M Y, h:i A',strtotime($event['registrationDeadline'])):'At event start')?></strong></p><p><small>Capacity and fee</small><strong><?= (int)$event['capacity']?> students · RM <?=number_format((float)$event['fee'],2)?></strong></p><p><small>Created by</small><strong><?=school_h($event['organizer']??'—')?><?=($publicId=school_public_person_id($pdo,(int)($event['organizerID']??0)))!==''?' · '.school_h($publicId):''?></strong></p><details class="event-note-details"><summary>Principal-only note</summary><p><?=nl2br(school_h($event['principalNote']??'—'))?></p></details></div></section>
<section class="portal-card"><h2>Committee assignments</h2><div class="event-detail-people"><?php if(!$tasks):?><p>No committee teachers assigned.</p><?php endif;?><?php foreach($tasks as $task):?><article><span><?=school_h($task['taskStatus'])?></span><h3><?=school_h($task['taskTitle'])?></h3><p><?=nl2br(school_h($task['taskDescription']?:'No task description.'))?></p><strong><?=school_h($task['name'])?></strong><small><?=school_h(school_public_person_id($pdo,(int)$task['userID']))?> · <?=school_h($task['email'])?></small></article><?php endforeach;?></div></section>
<section class="portal-card"><h2>Student registrations <span class="event-section-count"><?=count($roster)?></span></h2><div class="event-student-cards"><?php if(!$roster):?><p>No student registrations yet.</p><?php endif;?><?php foreach($roster as $student):?><article class="event-student-card"><header><div><h3><?=school_h($student['studentName'])?></h3><span><?=school_h($student['status'])?></span></div><small>Registration #<?= (int)$student['registrationID']?></small></header><p>Student ID <?=school_h($student['studentID'])?> · <?=school_h($student['studentEmail'])?></p><p>Class: <?=school_h(($student['formLevel']??'').' · '.($student['class']??'Not set'))?> · Registered <?=school_h($student['registrationDate'])?></p><div class="event-student-meta"><div><small>Attendance</small><strong><?=school_h($student['attendanceStatus']??'Not recorded')?> · <?=school_h($student['proofStatus']??'No proof')?></strong><?php if(!empty($student['proofFile'])):?><a href="<?=school_h($student['proofFile'])?>" target="_blank" rel="noopener">View attendance proof</a><?php endif;?></div><div><small>Financial assistance</small><strong><?=school_h($student['assistanceDetails']??'No application')?></strong></div><div><small>Event payments</small><strong><?=school_h($student['paymentDetails']??'No payment submitted')?></strong></div></div></article><?php endforeach;?></div></section>
<section class="portal-card" id="event-feedback"><h2>Student feedback <span class="event-section-count"><?=count($feedback)?></span></h2><div class="event-feedback-grid"><?php if(!$feedback):?><p>No feedback submitted for this event.</p><?php endif;?><?php foreach($feedback as $item):?><article><header><strong><?=school_h($item['name'])?> · <?= (int)$item['rating']?>/5</strong><small><?=school_h(school_public_person_id($pdo,(int)$item['userID']))?> · <?=school_h($item['submittedAt'])?></small></header><p><?=nl2br(school_h($item['comments']))?></p><?php if($item['photoPath']):?><a class="feedback-photo-open" data-proof-viewer data-proof-type="image" data-proof-title="Feedback photo" href="<?=school_h($item['photoPath'])?>"><span>View photo</span></a><?php endif;?><form method="post" onsubmit="return confirm('Remove this feedback from event records?')"><input type="hidden" name="csrf" value="<?=school_h($csrf)?>"><button class="small-button danger" name="delete_feedback" value="<?=(int)$item['feedbackID']?>">Delete feedback</button></form></article><?php endforeach;?></div></section></div></main></body></html>











